-- Explicações por artigo — Código Penal (Decreto-Lei 2.848/1940). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Trata da lei penal no tempo. Ninguém pode ser punido por fato que lei posterior deixa de considerar crime (abolitio criminis): cessam a execução e os efeitos penais da condenação. E a lei posterior que, de qualquer modo, favorecer o agente se aplica aos fatos anteriores, mesmo que já exista sentença condenatória transitada em julgado.', '["Abolitio criminis: a lei nova deixa de considerar o fato crime e cessam a execução e os efeitos penais da sentença.","Lei posterior mais favorável retroage, inclusive sobre fatos já decididos por sentença com trânsito em julgado."]'::jsonb, '["Retroage a lei MAIS BENÉFICA (novatio legis in mellius); a lei mais gravosa não retroage.","A abolição elimina os efeitos PENAIS da condenação; efeitos civis (como a obrigação de reparar) são tema à parte."]'::jsonb, 'Uma lei nova descriminaliza uma conduta. Quem cumpre pena por ela tem a execução encerrada, mesmo com condenação definitiva.', '["Assertiva que nega retroatividade à lei posterior mais benéfica após o trânsito em julgado contraria o parágrafo único."]'::jsonb, '[{"termo":"Abolitio criminis","significado":"Lei nova que torna o fato atípico, apagando o crime."},{"termo":"Trânsito em julgado","significado":"Decisão da qual não cabe mais recurso."}]'::jsonb, '["Art. 3º (lei excepcional ou temporária)","Art. 4º (tempo do crime)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Lei excepcional ou temporária é ultra-ativa: mesmo depois de acabar o período de sua duração ou de cessarem as circunstâncias que a motivaram, ela continua a ser aplicada ao fato praticado durante sua vigência.', '["Aplica-se a lei excepcional ou temporária ao fato praticado enquanto ela vigorava, mesmo após o fim do prazo ou das circunstâncias."]'::jsonb, '["É exceção à regra de que a lei posterior mais benéfica retroage: aqui a lei vencida ainda alcança o fato praticado na sua vigência."]'::jsonb, 'Uma lei criada só para o período de uma calamidade define um crime. Passada a calamidade, quem o cometeu durante ela ainda responde por ele.', '["Assertiva que afirma que o fim da vigência da lei temporária impede punir fatos ocorridos durante ela contraria o art. 3º."]'::jsonb, '[{"termo":"Ultra-atividade","significado":"Aplicação da lei mesmo depois de revogada ou vencida."}]'::jsonb, '["Art. 2º (abolitio criminis e lei mais benéfica)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Define o tempo do crime: considera-se praticado no momento da ação ou omissão, ainda que outro seja o momento do resultado (teoria da atividade).', '["Tempo do crime = momento da ação ou omissão.","O momento do resultado pode ser outro e não muda o tempo do crime."]'::jsonb, '["Diferente do lugar do crime (art. 6º), que considera ação ou omissão E resultado.","O tempo do crime define, por exemplo, qual lei se aplica e a imputabilidade."]'::jsonb, 'A vítima é ferida em março e morre em junho. O crime é considerado praticado em março, quando houve a ação.', '["Assertiva que fixa o tempo do crime no momento do resultado erra: vale o da ação ou omissão (teoria da atividade)."]'::jsonb, '[{"termo":"Teoria da atividade","significado":"O crime considera-se praticado quando se age (ou se omite), não quando o resultado ocorre."}]'::jsonb, '["Art. 6º (lugar do crime)","Art. 27 (menoridade)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Territorialidade: aplica-se a lei brasileira ao crime cometido no território nacional, sem prejuízo de convenções, tratados e regras de direito internacional. O território, para fins penais, inclui por extensão embarcações e aeronaves brasileiras públicas ou a serviço do governo onde quer que estejam, e as mercantes ou privadas brasileiras que estejam no espaço aéreo correspondente ou em alto-mar. Também se aplica a lei brasileira a crimes a bordo de aeronaves e embarcações estrangeiras privadas que estejam em pouso no território nacional ou em voo no espaço aéreo correspondente, ou em porto ou mar territorial do Brasil.', '["Regra: lei brasileira para crimes cometidos no território nacional (ressalvados tratados e direito internacional).","§1º: extensão do território: embarcações e aeronaves brasileiras públicas ou a serviço do governo, onde quer que estejam.","§1º: mercantes ou privadas brasileiras: extensão quando no espaço aéreo correspondente ou em alto-mar.","§2º: também se aplica a crimes a bordo de aeronaves/embarcações estrangeiras privadas em pouso, voo no espaço aéreo correspondente, porto ou mar territorial do Brasil."]'::jsonb, '["Públicas ou a serviço do governo: extensão do território onde quer que estejam. Privadas ou mercantes: só em alto-mar ou no espaço aéreo correspondente.","O art. 5º ressalva tratados e convenções: a regra é de territorialidade MITIGADA."]'::jsonb, 'Um crime ocorre dentro de uma aeronave militar brasileira em outro país: considera-se cometido em território brasileiro por extensão.', '["Assertiva que aplica extensão do território a qualquer navio privado brasileiro, em qualquer lugar, ignora a distinção do §1º (alto-mar ou espaço aéreo correspondente)."]'::jsonb, '[{"termo":"Território por extensão","significado":"Locais que a lei equipara ao território nacional, como certas aeronaves e embarcações."}]'::jsonb, '["Art. 6º (lugar do crime)","Art. 7º (extraterritorialidade)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Define o lugar do crime pela teoria da ubiquidade: considera-se praticado no lugar em que ocorreu a ação ou omissão, no todo ou em parte, bem como onde se produziu ou deveria produzir-se o resultado.', '["Lugar do crime: onde ocorreu a ação ou omissão (no todo ou em parte).","Também onde se produziu, ou deveria produzir-se, o resultado."]'::jsonb, '["Teoria da ubiquidade (mista): vale tanto o lugar da conduta quanto o do resultado, ao contrário do tempo do crime (art. 4º).","Inclui o lugar onde o resultado DEVERIA ocorrer (útil na tentativa)."]'::jsonb, 'Um disparo é feito em um país e a vítima morre no Brasil. O crime considera-se praticado também no Brasil.', '["Assertiva que limita o lugar do crime ao local da ação erra: o art. 6º adota a ubiquidade."]'::jsonb, '[{"termo":"Ubiquidade","significado":"O crime se considera praticado tanto onde se agiu quanto onde o resultado ocorreu ou deveria ocorrer."}]'::jsonb, '["Art. 4º (tempo do crime)","Art. 5º (territorialidade)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Extraterritorialidade: casos em que a lei brasileira se aplica a crimes cometidos no estrangeiro. Há hipóteses incondicionadas (crimes contra a vida ou a liberdade do Presidente, contra o patrimônio ou a fé pública de entes públicos, contra a administração pública por quem a serve, e genocídio quando o agente é brasileiro ou domiciliado no Brasil) e condicionadas (crimes que o Brasil se obrigou a reprimir por tratado, praticados por brasileiro, e os ocorridos em aeronaves ou embarcações brasileiras mercantes ou privadas, quando não julgados no estrangeiro), que exigem os requisitos dos parágrafos.', '["I: sujeitos à lei brasileira, no exterior: crimes contra a vida ou a liberdade do Presidente da República; contra o patrimônio ou a fé pública da União, DF, Estados, Territórios, Municípios, empresas públicas, sociedades de economia mista, autarquias ou fundações públicas; contra a administração pública, por quem está a seu serviço; genocídio, quando o agente for brasileiro ou domiciliado no Brasil.","II: crimes que, por tratado ou convenção, o Brasil se obrigou a reprimir; praticados por brasileiro; praticados em aeronaves ou embarcações brasileiras, mercantes ou privadas, quando em território estrangeiro e aí não julgados.","Os parágrafos do artigo estabelecem condições (como entrada do agente no território nacional) para as hipóteses do inciso II e para casos de estrangeiro."]'::jsonb, '["Inciso I = extraterritorialidade INCONDICIONADA; inciso II = CONDICIONADA.","No genocídio, a lei brasileira se aplica se o agente for brasileiro ou domiciliado no Brasil.","Confira no texto oficial os parágrafos com as condições antes de responder questões sobre hipóteses do inciso II."]'::jsonb, 'Brasileiro comete um crime na Argentina e entra no território nacional: pode responder no Brasil se atendidas as condições do inciso II.', '["Assertiva que trata como condicionada a extraterritorialidade dos crimes contra a vida ou a liberdade do Presidente da República erra: é incondicionada."]'::jsonb, '[{"termo":"Extraterritorialidade","significado":"Aplicação da lei brasileira a crimes cometidos fora do Brasil."}]'::jsonb, '["Art. 5º (territorialidade)","Art. 8º (pena cumprida no estrangeiro)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Evita punição dupla pelo mesmo crime: a pena cumprida no estrangeiro atenua a pena imposta no Brasil pelo mesmo crime, quando diversas, ou é computada nela, quando idênticas.', '["Penas diversas: a pena cumprida fora atenua a imposta no Brasil.","Penas idênticas: a pena cumprida fora é computada (descontada)."]'::jsonb, '["A regra distingue pena DIVERSA (atenua) de pena IDÊNTICA (computa)."]'::jsonb, 'Quem cumpriu 2 anos de prisão no exterior pelo mesmo crime tem esse tempo computado se a condenação no Brasil também for de prisão.', '["Assertiva que ignora a pena cumprida no exterior na fixação da pena no Brasil contraria o art. 8º."]'::jsonb, '[{"termo":"Bis in idem","significado":"Dupla punição pelo mesmo fato."}]'::jsonb, '["Art. 7º (extraterritorialidade)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Trata da eficácia de sentença estrangeira: quando a aplicação da lei brasileira produziria as mesmas consequências, ela pode ser homologada no Brasil para obrigar o condenado à reparação do dano, restituições e outros efeitos civis, ou sujeitá-lo a medida de segurança. A homologação depende de pedido da parte interessada (efeitos civis) ou, para os outros efeitos, de tratado de extradição com o país de origem da sentença ou, sem tratado, de requisição do Ministro da Justiça.', '["Homologação para efeitos civis (reparação, restituições) ou medida de segurança.","Efeitos civis: depende de pedido da parte interessada.","Outros efeitos: depende de tratado de extradição ou, na falta, de requisição do Ministro da Justiça."]'::jsonb, '["A sentença estrangeira só é homologada para os efeitos listados, e conforme as condições do parágrafo único."]'::jsonb, 'Sentença estrangeira que condena à reparação do dano pode ser homologada no Brasil a pedido da vítima.', '["Assertiva que dispensa qualquer requisito para homologar sentença estrangeira contraria o parágrafo único."]'::jsonb, '[{"termo":"Homologação","significado":"Reconhecimento oficial da validade da sentença estrangeira no Brasil."}]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Contagem de prazo penal: o dia do começo inclui-se no cômputo e os dias, meses e anos contam-se pelo calendário comum.', '["O dia do começo inclui-se no prazo.","Conta-se pelo calendário comum (dias, meses e anos)."]'::jsonb, '["Diferente do prazo processual, em que em regra se exclui o dia do começo: o prazo penal inclui o dia inicial e é improrrogável."]'::jsonb, 'Uma pena de um mês que começa a contar em dez de março termina em nove de abril, pois o dia do começo entra na contagem.', '["Assertiva que manda excluir o dia do começo na contagem do prazo penal contraria o art. 10."]'::jsonb, '[]'::jsonb, '["Art. 11 (frações não computáveis)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-10'
