insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Trata do nexo causal. O resultado de que depende a existência do crime só é imputável a quem lhe deu causa; causa é a ação ou omissão sem a qual o resultado não teria ocorrido (teoria da equivalência dos antecedentes). A superveniência de causa relativamente independente exclui a imputação quando, por si só, produziu o resultado, imputando-se porém os fatos anteriores. A omissão é penalmente relevante quando o omitente devia e podia agir para evitar o resultado, e o dever de agir incumbe a quem tenha por lei obrigação de cuidado, proteção ou vigilância, assumiu a responsabilidade de impedir o resultado ou criou o risco com seu comportamento anterior.', '["Causa: ação ou omissão sem a qual o resultado não teria ocorrido.","§1º: causa superveniente relativamente independente que, por si só, produz o resultado exclui a imputação do resultado; os fatos anteriores continuam imputados.","§2º: omissão relevante quando o omitente devia e podia agir.","Dever de agir: obrigação legal de cuidado, proteção ou vigilância; assunção de responsabilidade; criação do risco por comportamento anterior."]'::jsonb, '["Só exclui a imputação a causa superveniente que, POR SI SÓ, produziu o resultado.","A omissão penalmente relevante exige PODER agir, além do dever de agir.","As três hipóteses de dever de agir são cobradas literalmente."]'::jsonb, 'A vítima é ferida e, no caminho do hospital, morre em um incêndio sem relação com o ferimento. A causa superveniente produziu sozinha a morte: o agente responde pelos atos anteriores (lesão), não pelo homicídio.', '["Assertiva que dispensa a possibilidade de agir para a omissão relevante erra: o texto exige que o omitente devia e podia agir."]'::jsonb, '[{"termo":"Nexo causal","significado":"Ligação entre a conduta e o resultado."},{"termo":"Equivalência dos antecedentes","significado":"Teoria segundo a qual toda condição sem a qual o resultado não ocorreria é causa."}]'::jsonb, '["Art. 18 (dolo e culpa)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Define crime consumado (quando reúne todos os elementos de sua definição legal) e crime tentado (iniciada a execução, não se consuma por circunstâncias alheias à vontade do agente). Salvo disposição em contrário, a tentativa é punida com a pena do crime consumado diminuída de um a dois terços.', '["Consumado: reúnem-se todos os elementos da definição legal.","Tentado: execução iniciada e não consumação por circunstâncias alheias à vontade do agente.","Pena da tentativa: a do crime consumado, diminuída de um a dois terços, salvo disposição em contrário."]'::jsonb, '["A não consumação deve ocorrer por circunstâncias ALHEIAS à vontade do agente (se for voluntária, veja o art. 15).","A diminuição é de um a dois terços, e a lei pode dispor de modo diverso."]'::jsonb, 'O agente dispara para matar, mas a vítima é socorrida e sobrevive: tentativa, com pena reduzida de um a dois terços.', '["Assertiva que fixa a redução da tentativa em até a metade erra: é de um a dois terços."]'::jsonb, '[{"termo":"Iter criminis","significado":"Caminho percorrido do crime, da cogitação à consumação."}]'::jsonb, '["Art. 15 (desistência voluntária)","Art. 17 (crime impossível)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-14'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Desistência voluntária e arrependimento eficaz: o agente que voluntariamente desiste de prosseguir na execução ou impede que o resultado se produza só responde pelos atos já praticados.', '["Desistência voluntária: desiste de prosseguir na execução.","Arrependimento eficaz: impede que o resultado se produza.","Em ambos: responde só pelos atos já praticados."]'::jsonb, '["Exige VOLUNTARIEDADE (não necessariamente espontaneidade).","Não é tentativa: a não consumação decorre da vontade do agente, não de circunstâncias alheias."]'::jsonb, 'O agente, podendo continuar, para de agredir e socorre a vítima: responde só pelas lesões já causadas.', '["Assertiva que pune o agente que desistiu voluntariamente como se tivesse tentado o crime inteiro contraria o art. 15."]'::jsonb, '[{"termo":"Arrependimento eficaz","significado":"O agente esgota os atos de execução, mas age para evitar o resultado e consegue."}]'::jsonb, '["Art. 14, II (tentativa)","Art. 16 (arrependimento posterior)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-15'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Arrependimento posterior: nos crimes cometidos sem violência ou grave ameaça à pessoa, se o agente repara o dano ou restitui a coisa, por ato voluntário, até o recebimento da denúncia ou da queixa, a pena é reduzida de um a dois terços.', '["Só em crimes sem violência ou grave ameaça à pessoa.","Reparação do dano ou restituição da coisa, por ato voluntário.","Até o recebimento da denúncia ou da queixa.","Efeito: redução de pena de um a dois terços."]'::jsonb, '["É causa de DIMINUIÇÃO de pena (não exclui o crime).","O marco temporal é o RECEBIMENTO da denúncia ou queixa."]'::jsonb, 'Quem comete um estelionato e devolve o valor integralmente antes do recebimento da denúncia pode ter a pena reduzida de um a dois terços.', '["Assertiva que aplica o arrependimento posterior a crime com grave ameaça à pessoa contraria o art. 16."]'::jsonb, '[]'::jsonb, '["Art. 15 (desistência e arrependimento eficaz)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-16'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Crime impossível: não se pune a tentativa quando, por ineficácia absoluta do meio ou por absoluta impropriedade do objeto, é impossível consumar-se o crime.', '["Ineficácia ABSOLUTA do meio.","Absoluta impropriedade do objeto.","Em ambos: impossível consumar o crime e a tentativa não é punida."]'::jsonb, '["Só a ineficácia ou impropriedade ABSOLUTAS afastam a punição; se forem relativas, pode haver tentativa."]'::jsonb, 'Tentar matar uma pessoa que já está morta (objeto absolutamente impróprio): crime impossível.', '["Assertiva que pune como tentativa o crime impossível por ineficácia absoluta do meio contraria o art. 17."]'::jsonb, '[{"termo":"Crime impossível","significado":"Tentativa que jamais poderia consumar-se, por isso não punida."}]'::jsonb, '["Art. 14, II"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-17'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Define crime doloso (o agente quis o resultado ou assumiu o risco de produzi-lo) e culposo (o agente deu causa ao resultado por imprudência, negligência ou imperícia). Salvo os casos expressos em lei, ninguém pode ser punido por fato previsto como crime senão quando o pratica dolosamente.', '["Doloso: quis o resultado ou assumiu o risco de produzi-lo.","Culposo: imprudência, negligência ou imperícia.","Parágrafo único: a regra é a punição por dolo; a culpa só pune quando a lei expressamente prevê."]'::jsonb, '["Dolo inclui o dolo direto (quis) e o eventual (assumiu o risco).","Crime culposo só existe quando previsto em lei."]'::jsonb, 'Quem dirige em alta velocidade na contramão, sem querer matar mas sabendo do risco e aceitando-o, pode ter dolo eventual.', '["Assertiva que pune qualquer fato típico mesmo a título de culpa, sem previsão legal, contraria o parágrafo único."]'::jsonb, '[{"termo":"Imprudência, negligência e imperícia","significado":"Modalidades de culpa: agir sem cautela, deixar de agir com o cuidado devido e falta de aptidão técnica."}]'::jsonb, '["Art. 19 (crime preterdoloso)","Art. 20 (erro de tipo)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-18'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Agravação pelo resultado: pelo resultado que agrava especialmente a pena só responde o agente que o houver causado ao menos culposamente (afasta a responsabilidade objetiva).', '["O resultado mais grave só é imputado se causado ao menos por culpa."]'::jsonb, '["Veda a responsabilidade objetiva: não basta o nexo causal, é preciso culpa pelo resultado agravador."]'::jsonb, 'Em uma lesão corporal seguida de morte, o resultado morte só é imputado se ao menos previsível ao agente.', '["Assertiva que imputa resultado agravador sem exigir dolo ou culpa contraria o art. 19."]'::jsonb, '[{"termo":"Responsabilidade objetiva","significado":"Responsabilização sem dolo ou culpa, vedada no Direito Penal."}]'::jsonb, '["Art. 18"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-19'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Erro sobre elemento do tipo: o erro sobre elemento constitutivo do tipo legal de crime exclui o dolo, mas permite a punição por crime culposo, se previsto em lei. Descriminantes putativas: é isento de pena quem, por erro plenamente justificado pelas circunstâncias, supõe situação de fato que, se existisse, tornaria a ação legítima; não há isenção quando o erro deriva de culpa e o fato é punível como culposo. Erro determinado por terceiro: responde pelo crime o terceiro que determina o erro. Erro sobre a pessoa: não isenta de pena e consideram-se as condições da pessoa contra quem o agente queria praticar o crime.', '["Caput: erro sobre elemento do tipo exclui o dolo; pode responder por culpa, se prevista.","§1º: descriminante putativa por erro plenamente justificado isenta de pena; se o erro deriva de culpa e há crime culposo, não há isenção.","§2º: responde o terceiro que determinou o erro.","§3º: erro sobre a pessoa não isenta de pena; valem as condições da pessoa visada."]'::jsonb, '["Erro de tipo EXCLUI o dolo (e pode deixar culpa).","Erro sobre a pessoa não beneficia o agente: consideram-se as qualidades da vítima VISADA.","No §1º a isenção só vale para erro plenamente justificado."]'::jsonb, 'Alguém atira em um vulto que, pelas circunstâncias, acredita ser um assaltante armado prestes a atacá-lo, mas era um vizinho. Se o erro era plenamente justificado, há descriminante putativa e o agente fica isento de pena (§1º).', '["Assertiva que diz que o erro sobre a pessoa isenta o agente de pena erra: não isenta."]'::jsonb, '[{"termo":"Descriminante putativa","significado":"Situação imaginada pelo agente que, se real, tornaria sua conduta legítima."}]'::jsonb, '["Art. 21 (erro de proibição)","Art. 23 a 25 (excludentes de ilicitude)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-20'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Erro sobre a ilicitude do fato (erro de proibição): o desconhecimento da lei é inescusável; o erro sobre a ilicitude do fato, se inevitável, isenta de pena; se evitável, pode diminuí-la de um sexto a um terço. Considera-se evitável o erro se o agente atua ou se omite sem consciência da ilicitude, quando lhe era possível, nas circunstâncias, ter ou atingir essa consciência.', '["O desconhecimento da lei é inescusável.","Erro de proibição inevitável: isenta de pena.","Erro de proibição evitável: pena diminuída de um sexto a um terço.","Evitável: era possível ter ou atingir a consciência da ilicitude."]'::jsonb, '["Desconhecer a LEI não exime (inescusável); o que pode isentar é o erro sobre a ILICITUDE do fato.","Inevitável isenta; evitável diminui de um sexto a um terço."]'::jsonb, 'Estrangeiro recém-chegado pratica um ato permitido em seu país e proibido aqui, sem como saber: erro inevitável, isento de pena.', '["Assertiva que afirma que o desconhecimento da lei isenta de pena erra: o art. 21 o declara inescusável."]'::jsonb, '[{"termo":"Erro de proibição","significado":"Erro sobre a ilicitude do fato, isto é, o agente pensa que a conduta é permitida."}]'::jsonb, '["Art. 20 (erro de tipo)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-21'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Coação irresistível e obediência hierárquica: se o fato é cometido sob coação irresistível ou em estrita obediência a ordem, não manifestamente ilegal, de superior hierárquico, só é punível o autor da coação ou da ordem.', '["Coação irresistível: só responde quem coagiu.","Obediência hierárquica: ordem NÃO manifestamente ilegal de superior hierárquico; só responde quem deu a ordem."]'::jsonb, '["A ordem não pode ser manifestamente ilegal; se for, o subordinado responde.","Exclui a culpabilidade (inexigibilidade de conduta diversa)."]'::jsonb, 'Funcionário cumpre ordem do chefe aparentemente regular, que depois se revela ilegal: só o chefe é punido.', '["Assertiva que isenta o subordinado que cumpre ordem manifestamente ilegal erra."]'::jsonb, '[]'::jsonb, '["Art. 21"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-22'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Excludentes de ilicitude: não há crime quando o agente pratica o fato em estado de necessidade, em legítima defesa ou em estrito cumprimento de dever legal ou no exercício regular de direito. O parágrafo único diz que, em qualquer dessas hipóteses, o agente responde pelo excesso doloso ou culposo.', '["Estado de necessidade.","Legítima defesa.","Estrito cumprimento de dever legal ou exercício regular de direito.","Excesso doloso ou culposo é punível."]'::jsonb, '["Excludentes de ilicitude: o fato é típico, mas lícito (não há crime).","O excesso, doloso ou culposo, é punido (parágrafo único).","O texto indica ''Vide ADPF 779'' no inciso II: confira a decisão do STF."]'::jsonb, 'O policial que, em estrito cumprimento do dever legal, efetua a prisão em flagrante não comete crime.', '["Assertiva que afasta a responsabilidade pelo excesso nas excludentes de ilicitude contraria o parágrafo único."]'::jsonb, '[{"termo":"Excludente de ilicitude","significado":"Situação que retira o caráter ilícito do fato típico."}]'::jsonb, '["Arts. 24 e 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-23'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Estado de necessidade: pratica o fato para salvar de perigo atual, que não provocou por sua vontade nem podia de outro modo evitar, direito próprio ou alheio, cujo sacrifício, nas circunstâncias, não era razoável exigir-se. Não pode alegá-lo quem tinha o dever legal de enfrentar o perigo. Se era razoável exigir o sacrifício do direito ameaçado, a pena pode ser reduzida de um a dois terços.', '["Perigo atual, não provocado voluntariamente, inevitável de outro modo.","Direito próprio ou alheio que não era razoável sacrificar.","§1º: quem tem o dever legal de enfrentar o perigo não pode alegar.","§2º: se era razoável exigir o sacrifício, a pena pode ser reduzida de um a dois terços."]'::jsonb, '["O perigo deve ser ATUAL (diferente da legítima defesa, que admite agressão atual OU iminente).","O bombeiro e o policial têm o dever legal de enfrentar o perigo (§1º)."]'::jsonb, 'Em naufrágio, alguém toma o único colete disponível para salvar a vida, sem poder evitar o perigo de outra forma: estado de necessidade.', '["Assertiva que permite a quem tem o dever legal de enfrentar o perigo invocar estado de necessidade contraria o §1º."]'::jsonb, '[]'::jsonb, '["Art. 23","Art. 25 (legítima defesa)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-24'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Legítima defesa: usando moderadamente dos meios necessários, repele injusta agressão, atual ou iminente, a direito seu ou de outrem. O parágrafo único considera também em legítima defesa o agente de segurança pública que repele agressão ou risco de agressão a vítima mantida refém durante a prática de crimes.', '["Requisitos: injusta agressão atual ou iminente; direito próprio ou de outrem; meios necessários usados moderadamente.","Parágrafo único: agente de segurança pública que repele agressão ou risco de agressão a refém também age em legítima defesa."]'::jsonb, '["Agressão ATUAL ou IMINENTE (a futura ou passada não autoriza).","A reação deve usar meios necessários E de forma moderada; o excesso é punível (art. 23).","O texto indica ''Vide ADPF 779'': confira a decisão do STF."]'::jsonb, 'Policial atira em sequestrador que ameaça matar o refém no momento da ação: legítima defesa de terceiro (parágrafo único).', '["Assertiva que admite legítima defesa contra agressão futura incerta erra: exige agressão atual ou iminente."]'::jsonb, '[{"termo":"Moderação","significado":"Uso proporcional dos meios necessários para repelir a agressão."}]'::jsonb, '["Art. 23, parágrafo único (excesso)","Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-25'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Inimputáveis: é isento de pena o agente que, por doença mental ou desenvolvimento mental incompleto ou retardado, era, ao tempo da ação ou omissão, inteiramente incapaz de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento. A pena pode ser reduzida de um a dois terços se o agente, por perturbação da saúde mental ou desenvolvimento mental incompleto ou retardado, não era inteiramente capaz (semi-imputabilidade).', '["Caput: inteiramente incapaz ao tempo da conduta: isento de pena (inimputável).","Parágrafo único: não inteiramente capaz: pena reduzida de um a dois terços (semi-imputável)."]'::jsonb, '["A capacidade é aferida ao TEMPO da ação ou omissão.","Inimputável: isento de pena; semi-imputável: redução de um a dois terços."]'::jsonb, 'Pessoa em surto psicótico, incapaz de compreender a ilicitude no momento do fato: isenta de pena.', '["Assertiva que fixa a redução do semi-imputável em até a metade erra: é de um a dois terços."]'::jsonb, '[{"termo":"Inimputável","significado":"Quem, por condição mental, não pode ser responsabilizado penalmente."}]'::jsonb, '["Art. 27","Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-26'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Menores de 18 anos são penalmente inimputáveis, ficando sujeitos às normas estabelecidas na legislação especial.', '["Menores de 18 anos: inimputáveis.","Sujeitam-se à legislação especial."]'::jsonb, '["A inimputabilidade é fixada por critério biológico (idade), sem exame de maturidade."]'::jsonb, 'Adolescente de 17 anos que pratica ato infracional responde pela legislação especial, não pelo Código Penal.', '["Assertiva que sujeita o menor de 18 anos às penas do Código Penal erra."]'::jsonb, '[]'::jsonb, '["Art. 26 (inimputabilidade por doença mental)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-27'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Emoção, paixão e embriaguez: não excluem a imputabilidade penal a emoção ou a paixão e a embriaguez, voluntária ou culposa, pelo álcool ou substância de efeitos análogos. É isento de pena quem, por embriaguez completa proveniente de caso fortuito ou força maior, era inteiramente incapaz de entender o caráter ilícito do fato ou de se determinar; a pena pode ser reduzida de um a dois terços se, nessas condições, não possuía plena capacidade.', '["Não excluem a imputabilidade: emoção, paixão, embriaguez voluntária ou culposa.","§1º: embriaguez completa por caso fortuito ou força maior, com incapacidade total: isento de pena.","§2º: embriaguez por caso fortuito ou força maior com capacidade reduzida: pena reduzida de um a dois terços."]'::jsonb, '["A embriaguez VOLUNTÁRIA ou CULPOSA não exclui a imputabilidade; só a fortuita ou de força maior pode isentar ou reduzir.","Fortuita/força maior + completa = isenção; + incompleta = redução."]'::jsonb, 'Quem bebe por vontade própria e comete crime não é isento de pena. Quem é forçado a ingerir álcool, ficando completamente incapaz, pode ser isento.', '["Assertiva que isenta de pena o agente em embriaguez voluntária completa contraria o art. 28, II."]'::jsonb, '[{"termo":"Caso fortuito e força maior","significado":"Fatos imprevisíveis ou inevitáveis que fogem ao controle do agente."}]'::jsonb, '["Art. 26"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-28'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Concurso de pessoas: quem, de qualquer modo, concorre para o crime incide nas penas a ele cominadas, na medida de sua culpabilidade. Se a participação for de menor importância, a pena pode ser diminuída de um sexto a um terço. Se algum dos concorrentes quis participar de crime menos grave, aplica-se-lhe a pena deste, aumentada até metade se o resultado mais grave era previsível.', '["Quem concorre de qualquer modo responde pelo crime, na medida de sua culpabilidade.","§1º: participação de menor importância: redução de um sexto a um terço.","§2º: quis participar de crime menos grave: pena deste, aumentada até metade se o resultado mais grave era previsível."]'::jsonb, '["Cada concorrente responde na medida da SUA culpabilidade.","§2º: a pena aumenta até metade somente se o resultado mais grave era PREVISÍVEL."]'::jsonb, 'Dois combinam um furto, e um deles, sem o outro querer, comete roubo. O que quis só o furto responde pelo crime menos grave, com aumento até metade se o roubo era previsível.', '["Assertiva que fixa a redução da participação de menor importância em até dois terços erra: é de um sexto a um terço."]'::jsonb, '[{"termo":"Participação de menor importância","significado":"Colaboração de pouca relevância para o crime."}]'::jsonb, '["Art. 30 (circunstâncias incomunicáveis)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-29'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Circunstâncias e condições de caráter pessoal não se comunicam entre os coautores e partícipes, salvo quando forem elementares do crime. Elementar é o dado que faz parte da definição do crime: se ele existe, comunica-se a todos que o conhecem.', '["Regra: circunstâncias e condições de caráter pessoal NÃO se comunicam.","Exceção: quando forem elementares do crime, comunicam-se."]'::jsonb, '["A qualidade de funcionário público é elementar de crimes como o peculato: o particular que concorre responde junto, se souber da condição.","Circunstância (ex.: um agravante pessoal) não se comunica; elementar sim."]'::jsonb, 'Um particular ajuda um funcionário a desviar dinheiro público: a condição de funcionário (elementar) se comunica e o particular responde pelo mesmo crime.', '["Assertiva que comunica toda circunstância pessoal a todos os coautores erra: só as elementares se comunicam."]'::jsonb, '[{"termo":"Elementar","significado":"Dado essencial da definição do crime; sem ele o crime não existe ou muda de natureza."}]'::jsonb, '["Art. 29 (concurso de pessoas)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-30'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O ajuste, a determinação ou instigação e o auxílio, salvo disposição expressa em contrário, não são puníveis se o crime não chega, pelo menos, a ser tentado. Ou seja: atos preparatórios do partícipe não bastam sem início de execução do crime.', '["Ajuste, determinação, instigação e auxílio não são puníveis se o crime sequer chega à tentativa.","Salvo disposição expressa em contrário."]'::jsonb, '["A participação é acessória: depende de o autor ao menos tentar o crime.","A ressalva ''salvo disposição expressa'' permite que a lei puna certos atos preparatórios como crime autônomo."]'::jsonb, 'Alguém instiga outro a furtar, mas o furto nem chega a ser iniciado: a instigação, por si, não é punível.', '["Assertiva que pune o partícipe mesmo quando o crime não chega a ser tentado, sem exceção legal, contraria o art. 31."]'::jsonb, '[{"termo":"Atos preparatórios","significado":"Atos anteriores ao início da execução do crime."}]'::jsonb, '["Art. 29","Art. 14, II (tentativa)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-31'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Lista as espécies de pena: privativas de liberdade, restritivas de direitos e de multa.', '["I – privativas de liberdade.","II – restritivas de direitos.","III – multa."]'::jsonb, '["Três espécies; a pena de morte não consta (a Constituição só admite em guerra declarada, tema fora deste artigo)."]'::jsonb, 'Uma condenação pode ser de reclusão (privativa de liberdade), substituída por restritivas de direitos, com multa.', '["Assertiva que inclui a prisão cautelar entre as espécies de pena erra: o art. 32 lista só as três espécies."]'::jsonb, '[]'::jsonb, '["Arts. 33 a 52 (espécies de pena)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-32'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regula os regimes de cumprimento da pena privativa de liberdade. A reclusão pode ser cumprida em regime fechado, semiaberto ou aberto. A detenção, em semiaberto ou aberto, salvo necessidade de transferência a regime fechado. O §2º traz os critérios iniciais conforme a quantidade de pena e a reincidência, e o §3º manda observar o art. 59. O §4º condiciona a progressão, para o condenado por crime contra a administração pública, à reparação do dano ou devolução do produto do ilícito.', '["Reclusão: fechado, semiaberto ou aberto. Detenção: semiaberto ou aberto, salvo necessidade de regime fechado.","§1º: fechado = estabelecimento de segurança máxima ou média; semiaberto = colônia agrícola, industrial ou similar; aberto = casa de albergado ou estabelecimento adequado.","§2º: execução progressiva, segundo o mérito do condenado.","§2º, a: pena superior a 8 anos começa em regime fechado.","§2º, b: não reincidente, pena superior a 4 e não superior a 8 anos, pode começar em semiaberto.","§2º, c: não reincidente, pena igual ou inferior a 4 anos, pode começar em aberto.","§3º: o regime inicial observa os critérios do art. 59.","§4º: crime contra a administração pública: progressão condicionada à reparação do dano ou devolução do produto do ilícito."]'::jsonb, '["Os limites de 4 e 8 anos são cobrados em quase toda prova; a letra b e a c valem para NÃO reincidente.","Detenção não começa em regime fechado (apenas transferência posterior).","A progressão no crime contra a administração pública exige reparação do dano."]'::jsonb, 'Condenado não reincidente a 6 anos de reclusão pode começar em regime semiaberto (§2º, b).', '["Assertiva que coloca o não reincidente condenado a pena superior a 8 anos em regime semiaberto desde o início contraria o §2º, a.","Assertiva que permite iniciar a detenção em regime fechado contraria o caput."]'::jsonb, '[{"termo":"Progressão de regime","significado":"Passagem para regime menos rigoroso conforme o mérito do condenado."}]'::jsonb, '["Art. 59 (fixação do regime)","Art. 34 a 36 (regras de cada regime)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-33'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regras do regime fechado: o condenado é submetido, no início do cumprimento, a exame criminológico de classificação para individualização da execução; fica sujeito a trabalho no período diurno e isolamento durante o repouso noturno. O trabalho é em comum dentro do estabelecimento, conforme as aptidões ou ocupações anteriores do condenado, e o trabalho externo é admissível em serviços ou obras públicas.', '["Exame criminológico de classificação no início do cumprimento.","Trabalho durante o dia e isolamento no repouso noturno.","Trabalho em comum dentro do estabelecimento, conforme as aptidões.","Trabalho externo admissível em serviços ou obras públicas."]'::jsonb, '["No fechado, o trabalho externo só em serviços ou obras PÚBLICAS."]'::jsonb, 'Condenado em regime fechado pode trabalhar fora em uma obra pública, voltando ao estabelecimento para repousar à noite.', '["Assertiva que permite trabalho externo em empresa privada no regime fechado contraria o §3º."]'::jsonb, '[{"termo":"Exame criminológico","significado":"Avaliação do condenado para individualizar a execução da pena."}]'::jsonb, '["Art. 35 (semiaberto)","Art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-34'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regras do regime semiaberto: aplica-se o caput do art. 34 (exame criminológico) ao condenado que inicie nesse regime; o condenado fica sujeito a trabalho em comum durante o dia em colônia agrícola, industrial ou estabelecimento similar; o trabalho externo é admissível, assim como a frequência a cursos supletivos profissionalizantes, de instrução de segundo grau ou superior.', '["Aplica-se o caput do art. 34 a quem inicia no semiaberto.","Trabalho em comum durante o dia em colônia agrícola, industrial ou similar.","Trabalho externo e frequência a cursos supletivos profissionalizantes, de segundo grau ou superior."]'::jsonb, '["No semiaberto o trabalho externo é admitido sem a limitação a obras públicas própria do fechado."]'::jsonb, 'O condenado em semiaberto pode trabalhar fora durante o dia e frequentar curso superior.', '["Assertiva que proíbe cursos de instrução superior no semiaberto contraria o §2º."]'::jsonb, '[]'::jsonb, '["Art. 34","Art. 36"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-35'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regime aberto: baseia-se na autodisciplina e no senso de responsabilidade do condenado. Ele deve, fora do estabelecimento e sem vigilância, trabalhar, frequentar curso ou exercer outra atividade autorizada, permanecendo recolhido durante o período noturno e nos dias de folga. É transferido do regime aberto se praticar fato definido como crime doloso, se frustrar os fins da execução ou se, podendo, não pagar a multa cumulativamente aplicada.', '["Baseia-se na autodisciplina e no senso de responsabilidade.","Trabalho, curso ou atividade autorizada, fora do estabelecimento e sem vigilância.","Recolhimento no período noturno e nos dias de folga.","Transferência se praticar crime doloso, frustrar os fins da execução ou, podendo, não pagar a multa cumulativa."]'::jsonb, '["A transferência por novo crime exige crime DOLOSO.","Não pagar a multa só justifica a transferência se o condenado PODIA pagar."]'::jsonb, 'Condenado em regime aberto que comete novo crime doloso é transferido para regime mais rigoroso.', '["Assertiva que transfere o condenado de regime aberto por qualquer crime, inclusive culposo, contraria o §2º."]'::jsonb, '[{"termo":"Casa de albergado","significado":"Estabelecimento do regime aberto, onde o condenado se recolhe à noite e nos dias de folga."}]'::jsonb, '["Art. 33, §1º, c"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-36'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As mulheres cumprem pena em estabelecimento próprio, observando-se os deveres e direitos inerentes à sua condição pessoal e, no que couber, as regras do capítulo.', '["Estabelecimento próprio para mulheres.","Respeito aos deveres e direitos inerentes à condição pessoal."]'::jsonb, '["Vale a separação por sexo no cumprimento da pena."]'::jsonb, 'Uma condenada cumpre pena em unidade prisional feminina, não em estabelecimento misto.', '["Assertiva que admite cumprimento da pena da mulher no mesmo estabelecimento dos homens contraria o art. 37."]'::jsonb, '[]'::jsonb, '["Art. 38"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-37'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O preso conserva todos os direitos não atingidos pela perda da liberdade, impondo-se a todas as autoridades o respeito à sua integridade física e moral.', '["Mantêm-se todos os direitos não atingidos pela perda da liberdade.","Dever de todas as autoridades de respeitar a integridade física e moral."]'::jsonb, '["A pena restringe a liberdade, não os demais direitos."]'::jsonb, 'O preso não perde direito à saúde ou à integridade física: agressão por agente público é violação do art. 38.', '["Assertiva que afirma que o condenado perde todos os direitos civis durante a pena erra: só os atingidos pela perda da liberdade."]'::jsonb, '[]'::jsonb, '["Art. 39","Art. 40"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-38'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O trabalho do preso é sempre remunerado, sendo-lhe garantidos os benefícios da Previdência Social.', '["Trabalho do preso sempre remunerado.","Garantidos os benefícios da Previdência Social."]'::jsonb, '["A palavra é ''sempre'' remunerado."]'::jsonb, 'O condenado que trabalha na unidade prisional recebe remuneração e tem direito a benefícios previdenciários.', '["Assertiva que permite trabalho do preso sem remuneração contraria o art. 39."]'::jsonb, '[]'::jsonb, '["Art. 38","Art. 40"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-39'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Remete à legislação especial a regulação dos direitos e deveres do preso (arts. 38 e 39), os critérios de revogação e transferência de regimes e as infrações disciplinares e sanções (hoje, principalmente a Lei de Execução Penal).', '["Legislação especial regula a matéria dos arts. 38 e 39.","Define deveres e direitos do preso, critérios para revogação e transferência de regimes e infrações disciplinares com sanções."]'::jsonb, '["O Código só dá as bases; os detalhes da execução estão em lei especial."]'::jsonb, 'As faltas disciplinares e suas sanções estão na lei de execução, não no Código Penal.', '["Assertiva que diz que o Código Penal detalha as infrações disciplinares do preso erra: remete à legislação especial."]'::jsonb, '[]'::jsonb, '["Art. 38","Art. 39"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-40'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condenado a quem sobrevém doença mental deve ser recolhido a hospital de custódia e tratamento psiquiátrico ou, à falta, a outro estabelecimento adequado.', '["Doença mental superveniente: recolhimento a hospital de custódia e tratamento psiquiátrico.","À falta, outro estabelecimento adequado."]'::jsonb, '["Trata da doença que SOBREVÉM durante a execução (não da inimputabilidade ao tempo do fato)."]'::jsonb, 'Condenado desenvolve esquizofrenia durante o cumprimento da pena e é transferido a hospital de custódia.', '["Assertiva que mantém o condenado com doença mental superveniente em estabelecimento comum contraria o art. 41."]'::jsonb, '[]'::jsonb, '["Art. 26 (inimputabilidade)","Art. 42"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-41'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Detração: computam-se na pena privativa de liberdade e na medida de segurança o tempo de prisão provisória, no Brasil ou no estrangeiro, o de prisão administrativa e o de internação em hospital de custódia ou estabelecimento adequado. (Na plataforma, o texto desta unidade aparece seguido da lista de penas restritivas de direitos do art. 43.)', '["Computam-se: prisão provisória (no Brasil ou no exterior), prisão administrativa e internação.","Vale para pena privativa de liberdade e para medida de segurança.","O texto exibido a seguir traz as penas restritivas de direitos: prestação pecuniária, perda de bens e valores, prestação de serviço à comunidade ou a entidades públicas, interdição temporária de direitos e limitação de fim de semana."]'::jsonb, '["Detração desconta o tempo de prisão provisória da pena final.","A lista de penas restritivas de direitos pertence ao art. 43, que aparece junto ao texto desta unidade."]'::jsonb, 'Quem ficou preso provisoriamente por 6 meses e é condenado tem esses 6 meses descontados da pena.', '["Assertiva que não desconta o tempo de prisão provisória cumprido no exterior contraria o art. 42."]'::jsonb, '[{"termo":"Detração","significado":"Desconto, da pena, do tempo de prisão ou internação anteriores."}]'::jsonb, '["Art. 44 (substituição por restritivas de direitos)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-42'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas restritivas de direitos são autônomas e substituem as privativas de liberdade quando: (I) a pena aplicada não for superior a quatro anos e o crime não tiver sido cometido com violência ou grave ameaça, ou, qualquer que seja a pena, se o crime for culposo; (II) o réu não for reincidente em crime doloso; (III) culpabilidade, antecedentes, conduta social, personalidade, motivos e circunstâncias indicarem que a substituição é suficiente. Os parágrafos tratam da substituição por multa ou por uma ou duas restritivas conforme a pena, da reincidência (substituição possível se socialmente recomendável e se a reincidência não for no mesmo crime), da conversão por descumprimento (com saldo mínimo de trinta dias) e da decisão do juiz da execução em nova condenação.', '["Requisitos: pena não superior a 4 anos e crime sem violência ou grave ameaça (ou crime culposo, qualquer pena); réu não reincidente em crime doloso; circunstâncias indicam suficiência.","§2º: condenação igual ou inferior a 1 ano: multa ou uma restritiva; superior a 1 ano: restritiva e multa, ou duas restritivas.","§3º: reincidente pode ter substituição se socialmente recomendável e se a reincidência não for no mesmo crime.","§4º: conversão em privativa de liberdade por descumprimento injustificado, com desconto do tempo cumprido e saldo mínimo de 30 dias.","§5º: nova condenação a pena privativa: o juiz da execução decide sobre a conversão."]'::jsonb, '["Crime culposo admite substituição qualquer que seja a pena.","Reincidência em crime DOLOSO impede a substituição, salvo o §3º.","O saldo mínimo de 30 dias na conversão é cobrado."]'::jsonb, 'Condenação de 3 anos por furto sem violência, réu primário: pode ser substituída por restritivas de direitos.', '["Assertiva que permite substituição em crime com violência à pessoa quando a pena é de 3 anos contraria o inciso I."]'::jsonb, '[]'::jsonb, '["Art. 43 (espécies)","Art. 45 a 48"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-44'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A substituição segue as regras dos arts. 46, 47 e 48. A prestação pecuniária consiste em pagamento em dinheiro à vítima, a seus dependentes ou a entidade pública ou privada com destinação social, em importância fixada pelo juiz, entre 1 e 360 salários mínimos, e é deduzida de eventual reparação civil. Se o beneficiário aceitar, pode consistir em prestação de outra natureza. A perda de bens e valores reverte ao Fundo Penitenciário Nacional, ressalvada a legislação especial, com teto no prejuízo causado ou no proveito obtido (o que for maior).', '["Prestação pecuniária: de 1 a 360 salários mínimos, paga à vítima, dependentes ou entidade com destinação social.","O valor pago é deduzido de eventual reparação civil, se coincidentes os beneficiários.","Com aceitação do beneficiário, pode ser prestação de outra natureza.","Perda de bens e valores: em favor do Fundo Penitenciário Nacional, ressalvada a legislação especial; teto = o maior entre prejuízo causado e proveito obtido."]'::jsonb, '["Limites da prestação pecuniária: não inferior a 1 nem superior a 360 salários mínimos.","A perda de bens vai para o Fundo Penitenciário Nacional."]'::jsonb, 'O juiz fixa prestação pecuniária de 10 salários mínimos em favor da vítima; esse valor é abatido de futura ação civil de reparação.', '["Assertiva que fixa o teto da prestação pecuniária em 100 salários mínimos erra: o texto diz 360."]'::jsonb, '[]'::jsonb, '["Art. 44","Art. 46"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-45'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prestação de serviços à comunidade ou a entidades públicas aplica-se a condenações superiores a seis meses de privação da liberdade e consiste em tarefas gratuitas atribuídas ao condenado, em entidades assistenciais, hospitais, escolas, orfanatos e similares, conforme suas aptidões, à razão de uma hora de tarefa por dia de condenação, sem prejudicar a jornada normal de trabalho. Se a pena substituída for superior a um ano, o condenado pode cumprir em menor tempo, nunca inferior à metade da pena privativa fixada.', '["Aplicável a condenações superiores a 6 meses.","Tarefas gratuitas, conforme as aptidões, em entidades assistenciais, hospitais, escolas, orfanatos e similares.","Uma hora de tarefa por dia de condenação, sem prejudicar a jornada normal.","Pena substituída superior a 1 ano: pode cumprir em menor tempo, nunca inferior à metade."]'::jsonb, '["Só para condenações SUPERIORES a seis meses.","Cumprimento em menor tempo exige pena superior a um ano e respeita o mínimo de metade."]'::jsonb, 'Condenado a 2 anos, com pena substituída por serviços, pode cumpri-la em tempo menor, mas não em menos de 1 ano.', '["Assertiva que permite prestação de serviços para condenações de qualquer duração erra: só superiores a seis meses."]'::jsonb, '[]'::jsonb, '["Art. 44","Art. 55"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-46'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Penas de interdição temporária de direitos: proibição do exercício de cargo, função ou atividade pública e de mandato eletivo; proibição do exercício de profissão, atividade ou ofício que dependam de habilitação especial, licença ou autorização do poder público; suspensão de autorização ou habilitação para dirigir veículo; e proibição de inscrever-se em concurso, avaliação ou exame públicos (o texto oficial lista os incisos I, II, III e V).', '["I – cargo, função ou atividade pública e mandato eletivo.","II – profissão, atividade ou ofício que dependam de habilitação, licença ou autorização.","III – suspensão de autorização ou habilitação para dirigir.","V – proibição de inscrever-se em concurso, avaliação ou exame públicos."]'::jsonb, '["A proibição de concursos públicos (inciso V) foi incluída por lei de 2011 e é frequentemente cobrada."]'::jsonb, 'Condenado por crime no exercício da função pública pode ficar proibido de exercer cargo público por um tempo.', '["Assertiva que exclui a proibição de inscrever-se em concurso público do rol de interdições contraria o inciso V."]'::jsonb, '[]'::jsonb, '["Arts. 56 e 57 (aplicação das interdições)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-47'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A limitação de fim de semana consiste na obrigação de permanecer, aos sábados e domingos, por 5 horas diárias, em casa de albergado ou outro estabelecimento adequado, podendo ser ministrados cursos e palestras ou atribuídas atividades educativas durante a permanência.', '["Aos sábados e domingos, 5 horas por dia.","Em casa de albergado ou outro estabelecimento adequado.","Cursos, palestras ou atividades educativas podem ser ministrados."]'::jsonb, '["Duração diária fixa: 5 horas."]'::jsonb, 'O condenado comparece à casa de albergado nos fins de semana por 5 horas diárias.', '["Assertiva que fixa a limitação de fim de semana em 8 horas diárias erra: são 5."]'::jsonb, '[]'::jsonb, '["Art. 43"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-48'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pena de multa consiste no pagamento ao fundo penitenciário da quantia fixada na sentença, calculada em dias-multa, no mínimo 10 e no máximo 360. O valor do dia-multa é fixado pelo juiz, não podendo ser inferior a um trigésimo do maior salário mínimo mensal vigente ao tempo do fato, nem superior a 5 vezes esse salário. A multa é atualizada, na execução, pelos índices de correção monetária.', '["Pagamento ao fundo penitenciário, em dias-multa.","Mínimo de 10 e máximo de 360 dias-multa.","Valor do dia-multa: de um trigésimo a 5 vezes o maior salário mínimo mensal vigente ao tempo do fato.","Atualização por correção monetária na execução."]'::jsonb, '["Quantidade de dias: 10 a 360; valor do dia: 1/30 a 5 salários mínimos.","O salário mínimo considerado é o vigente ao tempo do FATO."]'::jsonb, 'A sentença fixa 100 dias-multa, cada um com o valor de um trigésimo do salário mínimo vigente na data do crime.', '["Assertiva que fixa o máximo de dias-multa acima de 360 erra: o limite é 360."]'::jsonb, '[{"termo":"Dia-multa","significado":"Unidade em que se calcula a multa, multiplicando-se a quantidade de dias pelo valor de cada dia."}]'::jsonb, '["Arts. 50 a 52","Art. 60 (fixação da multa)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-49'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A multa deve ser paga dentro de 10 dias depois de transitada em julgado a sentença; a requerimento do condenado, o juiz pode permitir pagamento em parcelas mensais. A cobrança pode ser feita mediante desconto no vencimento ou salário quando a multa for aplicada isoladamente, cumulativamente com pena restritiva de direitos ou com suspensão condicional da pena. O desconto não incide sobre os recursos indispensáveis ao sustento do condenado e de sua família.', '["Prazo de pagamento: 10 dias após o trânsito em julgado.","Parcelamento mensal a requerimento, a critério do juiz.","Desconto em vencimento ou salário: multa isolada, com restritiva de direitos ou com suspensão condicional.","O desconto respeita o sustento do condenado e da família."]'::jsonb, '["Prazo de 10 dias, contado do TRÂNSITO EM JULGADO."]'::jsonb, 'Condenado a multa isolada pode ter o valor descontado de seu salário, preservada a parte necessária ao sustento da família.', '["Assertiva que permite desconto integral do salário erra: o desconto não pode atingir o necessário ao sustento."]'::jsonb, '[]'::jsonb, '["Art. 49","Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-50'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitada em julgado a sentença condenatória, a multa é executada perante o juiz da execução penal e considerada dívida de valor, aplicando-se as normas da dívida ativa da Fazenda Pública, inclusive as causas interruptivas e suspensivas da prescrição. Os §§1º e 2º foram revogados. O texto traz a indicação ''Vide ADI 7032'': confira a decisão no STF.', '["Execução da multa perante o juiz da execução penal.","Considerada dívida de valor, com normas da dívida ativa da Fazenda Pública.","Aplicam-se as causas interruptivas e suspensivas da prescrição da dívida ativa."]'::jsonb, '["O texto remete à ADI 7032: antes de memorizar a legitimidade para executar a multa, confira o que o STF decidiu."]'::jsonb, 'Não paga a multa, ela é cobrada como dívida de valor no juízo da execução penal.', '["Assertiva que converte a multa não paga em prisão contraria o art. 51 (a multa é dívida de valor)."]'::jsonb, '[{"termo":"Dívida de valor","significado":"Débito cobrado como dívida em dinheiro, sem converter-se em pena de prisão."}]'::jsonb, '["Arts. 49 e 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-51'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É suspensa a execução da pena de multa se sobrevém ao condenado doença mental.', '["Doença mental superveniente suspende a execução da multa."]'::jsonb, '["É a suspensão da EXECUÇÃO, não extinção da pena."]'::jsonb, 'Condenado a multa desenvolve doença mental: a cobrança é suspensa.', '["Assertiva que extingue a multa pela doença mental superveniente erra: o texto fala em suspensão."]'::jsonb, '[]'::jsonb, '["Art. 41 (doença mental e pena privativa)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-52'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os limites das penas privativas de liberdade são estabelecidos na sanção correspondente a cada tipo legal de crime.', '["Os limites de cada pena privativa estão na sanção de cada crime."]'::jsonb, '["A parte geral não fixa a pena de cada crime: ela vem no preceito secundário de cada tipo."]'::jsonb, 'O furto simples tem sua pena na própria definição do crime.', '["Assertiva que fixa os limites da pena de qualquer crime no art. 53 erra: dependem de cada tipo legal."]'::jsonb, '[]'::jsonb, '["Art. 59"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-53'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas restritivas de direitos são aplicáveis, independentemente de cominação na parte especial, em substituição à pena privativa de liberdade, fixada em quantidade inferior a 1 ano, ou nos crimes culposos (o texto desta unidade segue a redação ainda constante do Código; veja também o art. 44, com as regras atuais de substituição).', '["Aplicam-se em substituição, sem precisar estar previstas em cada crime.","Pena inferior a 1 ano, ou crimes culposos."]'::jsonb, '["As condições atuais de substituição (pena de até 4 anos) estão no art. 44; compare os dois artigos ao estudar."]'::jsonb, 'Em crime culposo, a pena privativa pode ser substituída por restritiva de direitos.', '["Assertiva que exige previsão de restritiva de direitos na parte especial para cada crime contraria o art. 54."]'::jsonb, '[]'::jsonb, '["Art. 44"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-54'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas restritivas de direitos dos incisos III, IV, V e VI do art. 43 têm a mesma duração da pena privativa de liberdade substituída, ressalvado o disposto no §4º do art. 46.', '["Mesma duração da pena privativa substituída.","Ressalva: o cumprimento em menor tempo do §4º do art. 46."]'::jsonb, '["A ressalva do art. 46, §4º, permite cumprir em menor tempo, nunca inferior à metade."]'::jsonb, 'Pena de 1 ano substituída por prestação de serviços tem, em regra, duração de 1 ano.', '["Assertiva que fixa duração menor da pena restritiva sem a ressalva do art. 46, §4º, contraria o art. 55."]'::jsonb, '[]'::jsonb, '["Art. 46, §4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-55'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas de interdição previstas nos incisos I e II do art. 47 aplicam-se para todo crime cometido no exercício de profissão, atividade, ofício, cargo ou função, sempre que houver violação dos deveres que lhes são inerentes.', '["Interdições dos incisos I e II do art. 47.","Para crimes cometidos no exercício de profissão, atividade, ofício, cargo ou função.","Quando há violação dos deveres inerentes."]'::jsonb, '["Exige o crime ligado ao exercício da atividade e violação de seus deveres."]'::jsonb, 'Médico que comete crime violando os deveres da profissão pode ser proibido de exercê-la por um período.', '["Assertiva que aplica a interdição a qualquer crime, mesmo sem relação com a atividade, contraria o art. 56."]'::jsonb, '[]'::jsonb, '["Art. 47, I e II"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-56'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pena de interdição do inciso III do art. 47 (suspensão de autorização ou habilitação para dirigir veículo) aplica-se aos crimes culposos de trânsito.', '["Suspensão de habilitação para dirigir: crimes CULPOSOS de trânsito."]'::jsonb, '["O art. 57 trata dos crimes culposos de trânsito; para crimes específicos de trânsito há legislação própria."]'::jsonb, 'Motorista condenado por homicídio culposo na direção de veículo pode ter a habilitação suspensa.', '["Assertiva que aplica a suspensão do art. 47, III, a qualquer crime doloso contraria o art. 57."]'::jsonb, '[]'::jsonb, '["Art. 47, III"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-57'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A multa prevista em cada tipo legal de crime tem os limites fixados no art. 49 e seus parágrafos. A multa do parágrafo único do art. 44 e do §2º do art. 60 aplica-se independentemente de cominação na parte especial.', '["Limites da multa: art. 49 e parágrafos.","Multa substitutiva (art. 44, parágrafo único e art. 60, §2º): aplicável mesmo sem previsão no tipo."]'::jsonb, '["A multa substitutiva não depende de estar prevista no crime."]'::jsonb, 'Pena de até 6 meses pode ser substituída por multa mesmo que o crime não preveja multa.', '["Assertiva que exige previsão de multa no tipo para a multa substitutiva contraria o parágrafo único."]'::jsonb, '[]'::jsonb, '["Arts. 49 e 60"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-58'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fixação da pena (primeira fase): o juiz, atendendo à culpabilidade, aos antecedentes, à conduta social, à personalidade do agente, aos motivos, às circunstâncias e consequências do crime e ao comportamento da vítima, estabelece, conforme seja necessário e suficiente para reprovação e prevenção do crime: as penas aplicáveis dentre as cominadas, a quantidade de pena dentro dos limites, o regime inicial de cumprimento e a substituição da pena privativa por outra espécie, se cabível. O texto traz ''Vide ADPF 1107'': confira a decisão do STF.', '["Circunstâncias judiciais: culpabilidade, antecedentes, conduta social, personalidade, motivos, circunstâncias, consequências do crime e comportamento da vítima.","Critério: necessário e suficiente para reprovação e prevenção do crime.","I – penas aplicáveis dentre as cominadas; II – quantidade de pena; III – regime inicial; IV – substituição, se cabível."]'::jsonb, '["São oito circunstâncias judiciais; o comportamento da VÍTIMA está entre elas.","O art. 59 define o regime inicial junto com o art. 33, §3º."]'::jsonb, 'O juiz analisa os antecedentes e a personalidade do réu para fixar a pena-base acima ou abaixo do mínimo.', '["Assertiva que exclui o comportamento da vítima das circunstâncias do art. 59 contraria o caput."]'::jsonb, '[{"termo":"Pena-base","significado":"Pena fixada na primeira fase, a partir das circunstâncias judiciais."}]'::jsonb, '["Art. 33, §3º","Art. 60"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-59'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na fixação da pena de multa o juiz deve atender, principalmente, à situação econômica do réu. A multa pode ser aumentada até o triplo se, por essa situação, for ineficaz mesmo aplicada no máximo. A pena privativa de liberdade aplicada, não superior a 6 meses, pode ser substituída pela de multa, observados os critérios dos incisos II e III do art. 44.', '["Critério principal: situação econômica do réu.","§1º: aumento da multa até o triplo se ineficaz mesmo no máximo.","§2º: pena privativa não superior a 6 meses pode ser substituída por multa (critérios do art. 44, II e III)."]'::jsonb, '["O aumento é até o TRIPLO e só se a multa for ineficaz no máximo.","Substituição por multa: pena de até 6 meses."]'::jsonb, 'Réu muito rico condenado ao máximo de dias-multa pode ter o valor aumentado até o triplo.', '["Assertiva que permite substituir por multa pena de 1 ano erra: o §2º trata de pena não superior a 6 meses."]'::jsonb, '[]'::jsonb, '["Art. 49","Art. 44, II e III"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-60'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Lista as agravantes genéricas: circunstâncias que SEMPRE agravam a pena, quando não constituem nem qualificam o crime. São a reincidência e, no inciso II, motivos e modos de agir que tornam o fato mais reprovável: motivo fútil ou torpe; conexão com outro crime; traição, emboscada ou dissimulação; veneno, fogo, explosivo, tortura ou meio insidioso ou cruel; crime contra ascendente, descendente, irmão ou cônjuge; abuso de autoridade ou de relações domésticas, de coabitação ou hospitalidade, ou violência contra a mulher na forma da lei específica; abuso de poder ou violação de dever do cargo, ofício, ministério ou profissão; crime contra criança, maior de 60 anos, enfermo ou mulher grávida; ofendido sob proteção imediata da autoridade; e outras hipóteses do inciso II (confira o texto completo, que inclui a ocasião de calamidade).', '["Só agravam quando NÃO constituem nem qualificam o crime (para evitar dupla valoração).","I – reincidência.","II, a: motivo fútil ou torpe.","II, b: para facilitar ou assegurar execução, ocultação, impunidade ou vantagem de outro crime.","II, c: traição, emboscada, dissimulação ou recurso que dificultou a defesa.","II, d: veneno, fogo, explosivo, tortura ou meio insidioso, cruel ou de perigo comum.","II, e: contra ascendente, descendente, irmão ou cônjuge.","II, f: abuso de autoridade, relações domésticas, coabitação ou hospitalidade, ou violência contra a mulher.","II, g: abuso de poder ou violação de dever inerente ao cargo, ofício, ministério ou profissão.","II, h: contra criança, maior de 60 anos, enfermo ou mulher grávida.","II, i: ofendido sob imediata proteção da autoridade."]'::jsonb, '["Se a circunstância já qualifica o crime (ex.: motivo torpe no homicídio qualificado), não pode agravar de novo.","As agravantes SEMPRE agravam, mas a lei não fixa o quanto: o juiz define."]'::jsonb, 'O crime cometido contra o próprio irmão ou contra pessoa maior de 60 anos tem a pena agravada na segunda fase da dosimetria.', '["Assertiva que aplica agravante que já é qualificadora do crime erra: o artigo só vale quando a circunstância não constitui nem qualifica o crime."]'::jsonb, '[{"termo":"Agravante genérica","significado":"Circunstância legal que aumenta a pena em qualquer crime, na segunda fase."}]'::jsonb, '["Art. 62","Art. 63 (reincidência)","Art. 68 (cálculo da pena)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-61'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Agravantes no concurso de pessoas: a pena é ainda agravada para o agente que promove ou organiza a cooperação no crime ou dirige a atividade dos demais; coage ou induz outrem à execução material do crime; instiga ou determina a cometer o crime alguém sujeito à sua autoridade ou não punível em virtude de condição ou qualidade pessoal; ou executa o crime, ou nele participa, mediante paga ou promessa de recompensa.', '["I – promove ou organiza a cooperação ou dirige os demais.","II – coage ou induz outrem à execução material.","III – instiga ou determina a cometer o crime alguém sujeito à sua autoridade ou não punível por condição pessoal.","IV – executa ou participa mediante paga ou promessa de recompensa."]'::jsonb, '["Voltadas ao concurso de pessoas: ligam-se ao papel de cada agente."]'::jsonb, 'O chefe que organiza o grupo e dirige os demais tem a pena agravada (inciso I).', '["Assertiva que aplica o art. 62 a quem comete o crime sozinho erra: pressupõe concurso de agentes."]'::jsonb, '[]'::jsonb, '["Art. 61","Art. 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-62'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Reincidência: verifica-se quando o agente comete novo crime depois de transitar em julgado a sentença que, no País ou no estrangeiro, o tenha condenado por crime anterior.', '["Novo crime depois do trânsito em julgado de sentença condenatória por crime anterior.","A condenação anterior pode ser no País ou no estrangeiro."]'::jsonb, '["O marco é o TRÂNSITO EM JULGADO da condenação anterior.","Conta condenação no estrangeiro."]'::jsonb, 'Quem, depois de condenação definitiva por furto, comete roubo é reincidente.', '["Assertiva que considera reincidente quem comete novo crime com condenação anterior ainda recorrível erra: exige trânsito em julgado."]'::jsonb, '[{"termo":"Reincidente","significado":"Quem comete novo crime após condenação definitiva por crime anterior."}]'::jsonb, '["Art. 64"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-63'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Efeitos da reincidência: não prevalece a condenação anterior se, entre a data do cumprimento ou extinção da pena e a infração posterior, tiver decorrido período superior a 5 anos, computado o período de prova da suspensão ou do livramento condicional, se não ocorrer revogação (período depurador). Não se consideram os crimes militares próprios e políticos.', '["Prazo depurador: mais de 5 anos entre cumprimento ou extinção da pena e a nova infração.","Computa-se o período de prova da suspensão ou do livramento, se não houve revogação.","Não se consideram crimes militares próprios e políticos."]'::jsonb, '["Superado o prazo de 5 anos, o agente volta a ser primário para fins de reincidência (mas os antecedentes podem ser tema à parte).","Crimes militares próprios e políticos não geram reincidência."]'::jsonb, 'Quem terminou de cumprir pena há mais de 5 anos e comete novo crime não é reincidente.', '["Assertiva que fixa o prazo depurador em 10 anos erra: o texto fala em mais de 5 anos."]'::jsonb, '[{"termo":"Período depurador","significado":"Tempo após o qual a condenação anterior deixa de gerar reincidência."}]'::jsonb, '["Art. 63"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-64'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Atenuantes genéricas: circunstâncias que SEMPRE atenuam a pena. Incluem ser o agente menor de 21 anos na data do fato ou maior de 70 na data da sentença (salvo crime com violência sexual contra a mulher, conforme a redação do texto); o desconhecimento da lei; ter o agente cometido o crime por relevante valor social ou moral; ter procurado, espontaneamente e com eficiência, logo após o crime, evitar ou minorar as consequências ou reparado o dano antes do julgamento; coação resistível, cumprimento de ordem de autoridade superior ou violenta emoção provocada por ato injusto da vítima; confissão espontânea perante a autoridade; e influência de multidão em tumulto, se não a provocou.', '["I – menor de 21 anos na data do fato ou maior de 70 na data da sentença (com a ressalva do texto).","II – desconhecimento da lei.","III, a: relevante valor social ou moral.","III, b: evitar ou minorar consequências ou reparar o dano antes do julgamento.","III, c: coação resistível, ordem de autoridade superior ou violenta emoção por ato injusto da vítima.","III, d: confissão espontânea da autoria perante a autoridade.","III, e: influência de multidão em tumulto, se não a provocou."]'::jsonb, '["Menor de 21: na data do FATO; maior de 70: na data da SENTENÇA.","Confissão deve ser ESPONTÂNEA e perante a autoridade.","A reparação do dano precisa ocorrer ANTES do julgamento (diferente do arrependimento posterior, até o recebimento da denúncia)."]'::jsonb, 'O réu confessa espontaneamente a autoria diante do delegado: incide a atenuante do inciso III, d.', '["Assertiva que considera a idade do agente na data da sentença para a atenuante da menoridade erra: é a data do fato."]'::jsonb, '[]'::jsonb, '["Art. 66","Art. 67"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-65'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Atenuante inominada: a pena pode ainda ser atenuada em razão de circunstância relevante, anterior ou posterior ao crime, embora não prevista expressamente em lei.', '["Circunstância relevante, anterior ou posterior ao crime.","Mesmo sem previsão expressa em lei.","É faculdade do juiz (''poderá'')."]'::jsonb, '["Diferente do art. 65 (''sempre atenuam''): aqui a atenuação é facultativa e aberta."]'::jsonb, 'O juiz reconhece como relevante o fato de o réu ter prestado socorro à vítima, ainda que isso não esteja listado no art. 65.', '["Assertiva que restringe as atenuantes ao rol do art. 65 erra: o art. 66 admite circunstância relevante não prevista."]'::jsonb, '[]'::jsonb, '["Art. 65"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-66'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Concurso de agravantes e atenuantes: a pena deve aproximar-se do limite indicado pelas circunstâncias preponderantes, entendendo-se como tais as que resultam dos motivos determinantes do crime, da personalidade do agente e da reincidência.', '["Prevalecem as circunstâncias preponderantes.","Preponderantes: motivos determinantes, personalidade do agente e reincidência."]'::jsonb, '["A reincidência está entre as preponderantes."]'::jsonb, 'Havendo confissão (atenuante) e reincidência (agravante), a reincidência pesa mais por ser preponderante.', '["Assertiva que exclui a reincidência das circunstâncias preponderantes contraria o art. 67."]'::jsonb, '[]'::jsonb, '["Arts. 61 a 66"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-67'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cálculo da pena (critério trifásico): primeiro fixa-se a pena-base pelo art. 59; depois consideram-se as circunstâncias atenuantes e agravantes; por último, as causas de diminuição e de aumento. No concurso de causas de aumento ou diminuição da parte especial, o juiz pode limitar-se a um só aumento ou a uma só diminuição, prevalecendo a que mais aumente ou diminua.', '["1ª fase: pena-base (art. 59).","2ª fase: atenuantes e agravantes.","3ª fase: causas de diminuição e de aumento.","Parágrafo único: concurso de causas da parte especial: pode aplicar só uma, prevalecendo a que mais aumente ou diminua."]'::jsonb, '["Ordem das fases: pena-base, atenuantes/agravantes, causas de aumento/diminuição.","O parágrafo único vale para causas da PARTE ESPECIAL."]'::jsonb, 'O juiz fixa a pena-base, aplica a atenuante da confissão e, por fim, aumenta pela causa de aumento prevista no tipo.', '["Assertiva que inverte a ordem, aplicando as causas de aumento antes das agravantes, contraria o art. 68."]'::jsonb, '[{"termo":"Sistema trifásico","significado":"Método de cálculo da pena em três fases sucessivas."}]'::jsonb, '["Art. 59","Arts. 61 a 67"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-68'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Concurso material: quando o agente, mediante mais de uma ação ou omissão, pratica dois ou mais crimes, idênticos ou não, aplicam-se cumulativamente as penas privativas de liberdade. Se há reclusão e detenção, executa-se primeiro a reclusão. Se foi aplicada pena privativa de liberdade, não suspensa, por um dos crimes, é incabível a substituição do art. 44 para os demais. Penas restritivas de direitos compatíveis cumprem-se simultaneamente; as demais, sucessivamente.', '["Mais de uma ação ou omissão, dois ou mais crimes: penas somadas.","Reclusão cumpre-se antes da detenção.","§1º: pena privativa não suspensa em um crime impede a substituição nos demais.","§2º: restritivas compatíveis: simultâneas; as demais: sucessivas."]'::jsonb, '["Concurso MATERIAL = pluralidade de condutas, penas somadas (cúmulo material).","A reclusão é executada primeiro."]'::jsonb, 'Em dias diferentes, o agente comete um roubo e uma extorsão: as penas são somadas.', '["Assertiva que aplica o cúmulo material a uma única ação com dois resultados erra: isso é concurso formal (art. 70)."]'::jsonb, '[{"termo":"Cúmulo material","significado":"Soma das penas de cada crime."}]'::jsonb, '["Art. 70","Art. 71"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-69'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Concurso formal: quando o agente, mediante uma só ação ou omissão, pratica dois ou mais crimes, idênticos ou não, aplica-se a mais grave das penas, ou, se iguais, só uma, aumentada de um sexto até metade. As penas se somam, porém, se a ação ou omissão é dolosa e os crimes resultam de desígnios autônomos (concurso formal impróprio). A pena não pode exceder a que seria cabível pela regra do concurso material.', '["Uma só ação ou omissão, dois ou mais crimes.","Pena: a mais grave (ou uma delas, se iguais) aumentada de um sexto até metade (exasperação).","Se dolosa e de desígnios autônomos: penas somadas (cúmulo).","Parágrafo único: limite — não pode exceder o que seria no concurso material."]'::jsonb, '["Concurso formal próprio: exasperação de 1/6 até a metade; impróprio (desígnios autônomos): cúmulo material.","A regra do art. 69 funciona como teto (parágrafo único)."]'::jsonb, 'Com uma só explosão, o agente causa a morte de duas pessoas sem querer ambas as mortes: concurso formal.', '["Assertiva que fixa o aumento do concurso formal em até dois terços erra: é de um sexto até a metade."]'::jsonb, '[{"termo":"Desígnios autônomos","significado":"Propósitos distintos do agente para cada resultado."}]'::jsonb, '["Art. 69","Art. 71"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-70'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Crime continuado: quando o agente, mediante mais de uma ação ou omissão, pratica dois ou mais crimes da mesma espécie e, pelas condições de tempo, lugar, maneira de execução e outras semelhantes, os subsequentes devem ser havidos como continuação do primeiro, aplica-se a pena de um só dos crimes, se idênticas, ou a mais grave, se diversas, aumentada de um sexto a dois terços. O parágrafo único trata dos crimes dolosos contra vítimas diferentes, com violência ou grave ameaça, em que o juiz pode aumentar a pena até o triplo, respeitados os limites dos arts. 70, parágrafo único e 75.', '["Dois ou mais crimes da mesma espécie, em condições semelhantes de tempo, lugar e modo de execução.","Pena de um só dos crimes (ou o mais grave), aumentada de um sexto a dois terços.","Parágrafo único: dolosos, vítimas diferentes, com violência ou grave ameaça: aumento até o triplo, observados os arts. 70 e 75."]'::jsonb, '["Aumento comum: de 1/6 a 2/3; no parágrafo único: até o TRIPLO.","Crimes da MESMA espécie (e condições semelhantes)."]'::jsonb, 'Funcionário desvia pequenas quantias da empresa toda semana pelo mesmo método: crime continuado.', '["Assertiva que aplica a mesma pena aumentada até a metade no crime continuado simples erra: é de um sexto a dois terços."]'::jsonb, '[{"termo":"Crime continuado","significado":"Ficção legal que trata várias condutas semelhantes como um só crime para fins de pena."}]'::jsonb, '["Art. 70","Art. 75"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-71'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No concurso de crimes, as penas de multa são aplicadas distinta e integralmente, isto é, somam-se sem exasperação.', '["Multas aplicadas de forma distinta e integral em cada crime."]'::jsonb, '["Mesmo no concurso formal ou no crime continuado, a multa é aplicada integralmente em cada crime."]'::jsonb, 'Em dois crimes, cada multa é calculada separadamente e ambas são cobradas.', '["Assertiva que aplica só uma multa aumentada no concurso de crimes contraria o art. 72."]'::jsonb, '[]'::jsonb, '["Arts. 69 a 71"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-72'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Erro na execução (aberratio ictus com unidade simples): quando, por acidente ou erro no uso dos meios de execução, o agente, em vez de atingir a pessoa que pretendia ofender, atinge pessoa diversa, responde como se tivesse praticado o crime contra aquela, atendendo ao §3º do art. 20. Se também atinge a pessoa pretendida, aplica-se o concurso formal do art. 70.', '["Atinge pessoa diversa da pretendida: responde como se tivesse atingido a visada.","Consideram-se as condições da pessoa visada (art. 20, §3º).","Se atinge também a pretendida: regra do art. 70."]'::jsonb, '["Vítima diversa: responde pelo crime como se tivesse atingido quem queria atingir.","Se atinge as duas pessoas: concurso formal."]'::jsonb, 'O agente atira para matar o desafeto, mas acerta um transeunte: responde como se tivesse matado o desafeto.', '["Assertiva que isenta o agente de pena quando atinge pessoa diversa da pretendida erra: responde como se tivesse atingido a pretendida."]'::jsonb, '[{"termo":"Aberratio ictus","significado":"Erro na execução: o golpe atinge pessoa ou coisa diversa da pretendida."}]'::jsonb, '["Art. 20, §3º","Art. 70","Art. 74"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-73'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Resultado diverso do pretendido (aberratio criminis): fora dos casos do art. 73, quando por acidente ou erro na execução sobrevém resultado diverso do pretendido, o agente responde por culpa, se o fato é previsto como crime culposo; se ocorre também o resultado pretendido, aplica-se a regra do concurso formal do art. 70.', '["Resultado diverso do pretendido: responde por culpa, se o fato é previsto como crime culposo.","Se ocorre também o resultado pretendido: art. 70."]'::jsonb, '["Só há punição se o fato diverso for previsto como crime CULPOSO.","Diferente do art. 73, em que a pessoa atingida é diversa; aqui o resultado é diverso."]'::jsonb, 'O agente quer apenas quebrar a vidraça de uma casa com uma pedra, mas ela atinge e fere um morador: o resultado (lesão) é diverso do pretendido (dano); responde por lesão corporal culposa, se prevista como crime culposo.', '["Assertiva que pune sempre a título de dolo o resultado diverso do pretendido erra: a regra é a culpa, se prevista."]'::jsonb, '[{"termo":"Aberratio criminis","significado":"Resultado diverso do pretendido por erro na execução."}]'::jsonb, '["Art. 73","Art. 70"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-74'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Limite das penas: o tempo de cumprimento das penas privativas de liberdade não pode ser superior a 40 anos. Se a soma das penas for superior a 40 anos, elas são unificadas para atender ao limite. Sobrevindo condenação por fato posterior ao início do cumprimento, faz-se nova unificação, desprezando o período já cumprido.', '["Limite de 40 anos de cumprimento.","Penas somadas acima de 40 anos são unificadas para atender ao limite.","Condenação por fato posterior: nova unificação, desprezando o período já cumprido."]'::jsonb, '["O limite é de 40 anos (alterado pela Lei 13.964/2019; antes era 30).","Na nova unificação, desconsidera-se o tempo já cumprido."]'::jsonb, 'Condenado a 100 anos de soma de penas cumpre no máximo 40 anos, salvo nova condenação por fato posterior.', '["Assertiva que fixa o limite máximo de cumprimento em 30 anos contraria o art. 75 atual."]'::jsonb, '[{"termo":"Unificação das penas","significado":"Redução da soma das penas ao limite máximo de cumprimento."}]'::jsonb, '["Art. 71, parágrafo único"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-75'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No concurso de infrações, executa-se primeiramente a pena mais grave.', '["Executa-se primeiro a pena mais grave."]'::jsonb, '["Ordem de execução: a mais grave vem primeiro."]'::jsonb, 'Com condenações de reclusão e de detenção, cumpre-se antes a mais grave.', '["Assertiva que determina a execução primeiro da pena mais leve erra: o art. 76 manda executar a mais grave."]'::jsonb, '[]'::jsonb, '["Art. 69"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-76'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Suspensão condicional da pena (sursis): a execução da pena privativa de liberdade não superior a 2 anos pode ser suspensa, por 2 a 4 anos, desde que o condenado não seja reincidente em crime doloso, a culpabilidade, os antecedentes, a conduta social e a personalidade, bem como os motivos e circunstâncias, autorizem o benefício, e não seja indicada ou cabível a substituição do art. 44. A condenação anterior a multa não impede o benefício. O sursis etário ou humanitário permite suspender, por 4 a 6 anos, pena não superior a 4 anos para maior de 70 anos ou por razões de saúde.', '["Pena privativa não superior a 2 anos; suspensão por 2 a 4 anos.","I – não reincidente em crime doloso.","II – culpabilidade, antecedentes, conduta social, personalidade, motivos e circunstâncias autorizam.","III – não seja indicada ou cabível a substituição do art. 44.","§1º: condenação anterior a multa não impede.","§2º: pena não superior a 4 anos, maior de 70 anos ou razões de saúde: suspensão por 4 a 6 anos."]'::jsonb, '["Sursis comum: pena até 2 anos, prazo de 2 a 4 anos; etário/humanitário: pena até 4 anos, prazo de 4 a 6 anos.","A reincidência impeditiva é em crime DOLOSO."]'::jsonb, 'Réu primário condenado a 1 ano e 6 meses, sem cabimento de substituição, pode ter a pena suspensa por 2 a 4 anos.', '["Assertiva que permite sursis a reincidente em crime doloso contraria o inciso I."]'::jsonb, '[{"termo":"Sursis","significado":"Suspensão condicional da pena, mediante condições."}]'::jsonb, '["Art. 78","Art. 44"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-77'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Durante o prazo da suspensão, o condenado fica sujeito à observação e ao cumprimento das condições do juiz. No primeiro ano do prazo, deve prestar serviços à comunidade ou submeter-se à limitação de fim de semana. Se reparou o dano, salvo impossibilidade, e as circunstâncias do art. 59 lhe forem inteiramente favoráveis, o juiz pode substituir essa exigência por condições cumulativas: proibição de frequentar determinados lugares, de ausentar-se da comarca sem autorização e comparecimento mensal a juízo para informar e justificar suas atividades.', '["Sujeição à observação e às condições fixadas pelo juiz.","§1º: no 1º ano: prestação de serviços à comunidade ou limitação de fim de semana.","§2º: com dano reparado e circunstâncias do art. 59 inteiramente favoráveis: proibição de frequentar lugares, de ausentar-se da comarca sem autorização e comparecimento mensal a juízo (cumulativas)."]'::jsonb, '["As três condições do §2º são aplicadas CUMULATIVAMENTE.","A substituição do §2º exige reparação do dano (salvo impossibilidade) e circunstâncias INTEIRAMENTE favoráveis."]'::jsonb, 'Com o dano reparado, o juiz pode trocar os serviços do primeiro ano por comparecimento mensal e proibição de sair da comarca.', '["Assertiva que torna alternativas as condições do §2º erra: são cumulativas."]'::jsonb, '[]'::jsonb, '["Art. 77","Arts. 46 e 48"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-78'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sentença pode especificar outras condições a que fica subordinada a suspensão, desde que adequadas ao fato e à situação pessoal do condenado.', '["Outras condições podem ser fixadas na sentença.","Devem ser adequadas ao fato e à situação pessoal do condenado."]'::jsonb, '["As condições adicionais devem ser adequadas (não arbitrárias)."]'::jsonb, 'O juiz acrescenta a obrigação de frequentar curso relacionado ao crime cometido.', '["Assertiva que permite condições sem relação com o fato ou a pessoa do condenado contraria o art. 79."]'::jsonb, '[]'::jsonb, '["Art. 78"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-79'
