insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Revogação obrigatória do livramento: ocorre se o liberado vem a ser condenado a pena privativa de liberdade, em sentença irrecorrível, por crime cometido durante a vigência do benefício, ou por crime anterior, observado o art. 84.', '["Condenação a pena privativa de liberdade em sentença irrecorrível.","I – por crime cometido durante o livramento.","II – por crime anterior, observado o art. 84."]'::jsonb, '["É revogação OBRIGATÓRIA e exige sentença irrecorrível e pena privativa de liberdade."]'::jsonb, 'Quem, solto em livramento, comete e é definitivamente condenado por novo crime tem o benefício revogado.', '["Assertiva que revoga o livramento por simples abertura de inquérito erra: exige condenação irrecorrível."]'::jsonb, '[]'::jsonb, '["Art. 87","Art. 88"]'::jsonb, 'under_review', 'claude'
