insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz não poderá declarar extinta a pena enquanto não passar em julgado a sentença do processo a que responde o liberado por crime cometido na vigência do livramento.', '["Extinção da pena fica condicionada ao trânsito em julgado do processo por crime cometido durante o livramento."]'::jsonb, '["Evita extinguir a pena enquanto pende processo por novo crime cometido no livramento."]'::jsonb, 'Terminado o prazo do livramento, a extinção da pena aguarda o desfecho do processo pelo novo crime.', '["Assertiva que permite declarar extinta a pena enquanto ainda tramita processo por crime cometido no livramento contraria o art. 89."]'::jsonb, '[]'::jsonb, '["Art. 86"]'::jsonb, 'under_review', 'claude'
